const stockLineSchema=z.object({itemId:z.string(),locationId:z.string(),destinationLocationId:z.string().optional(),quantity:decimalText,unitId:z.string().optional(),unitCost:decimalText.optional()});
const createDocSchema=z.object({type:z.enum(["OPENING","RECEIPT","ISSUE","TRANSFER","ADJUSTMENT"]),financialYearId:z.string(),effectiveDate:date,reason:z.string().max(1000).optional(),lines:z.array(stockLineSchema).min(1).max(500)});
route("post", "/stock-documents", "inventory.create", async (req,res)=>{
  const input=createDocSchema.parse(req.body);if(input.type==="ADJUSTMENT"&&!input.reason?.trim())throw fail("Stock adjustments require a reason.");const required={OPENING:"inventory.opening.manage",RECEIPT:"inventory.receive",ISSUE:"inventory.issue",TRANSFER:"inventory.transfer",ADJUSTMENT:"inventory.adjust"}[input.type];if(!req.auth!.permissions.includes(required))throw fail("You do not have permission for this stock document type.",403,"FORBIDDEN"); const fy=await prisma.financialYear.findFirst({where:{id:input.financialYearId,companyId:company(req),status:"OPEN",startDate:{lte:input.effectiveDate},endDate:{gte:input.effectiveDate}}});if(!fy)throw fail("An open financial year containing the effective date is required.",409,"FINANCIAL_YEAR_INVALID");
  const created=await prisma.$transaction(async tx=>{const type=input.type;
    let openingBatch=type==="OPENING"?await tx.openingStockBatch.findUnique({where:{companyId:company(req)}}):null;if(type==="OPENING"&&openingBatch&&openingBatch.status!=="DRAFT")throw fail("Initial opening stock has already been finalized.",409,"OPENING_EXISTS");if(type==="OPENING"&&!openingBatch)openingBatch=await tx.openingStockBatch.create({data:{companyId:company(req)}});if(type==="OPENING"&&openingBatch&&await tx.stockDocument.count({where:{companyId:company(req),openingBatchId:openingBatch.id}}))throw fail("Opening stock must be a single document containing all opening lines.",409,"OPENING_BATCH_DOCUMENT_EXISTS");
    const document=await tx.stockDocument.create({data:{companyId:company(req),financialYearId:fy.id,openingBatchId:openingBatch?.id??null,type,status:"DRAFT",documentNumber:`${type}-${randomUUID()}`,effectiveDate:input.effectiveDate,reason:input.reason,createdByUserId:req.auth!.userId}});
    for(let i=0;i<input.lines.length;i++){const line=input.lines[i];const item=await tx.item.findFirst({where:{id:line.itemId,companyId:company(req),active:true}});if(!item)throw fail("Item not found or inactive.",404);const unitId=line.unitId??item.baseUnitId;let factor=new Prisma.Decimal(1);if(unitId!==item.baseUnitId){const conv=await tx.itemUnitConversion.findFirst({where:{companyId:company(req),itemId:item.id,unitId,active:true,effectiveFrom:{lte:input.effectiveDate},OR:[{effectiveTo:null},{effectiveTo:{gte:input.effectiveDate}}]}});if(!conv)throw fail("No effective conversion exists for this item and unit.");factor=conv.factorToBase;}const entered=roundQuantity(decimal(line.quantity));if(entered.isZero())throw fail("Quantity must be nonzero.");if(type!=="ADJUSTMENT"&&entered.isNegative())throw fail("Quantity must be positive for this document type.");const loc=await tx.warehouseLocation.findFirst({where:{id:line.locationId,companyId:company(req),active:true}});if(!loc||!(loc.type==="BIN"||loc.type==="WAREHOUSE"))throw fail("Stock must be assigned to an active warehouse or bin.");let destId=line.destinationLocationId??null;if(type==="TRANSFER"){if(!destId)throw fail("Transfers require a destination.");const dest=await tx.warehouseLocation.findFirst({where:{id:destId,companyId:company(req),active:true,type:{in:["BIN","WAREHOUSE"]}}});if(!dest||dest.id===loc.id)throw fail("Transfer destination is invalid.");} const base=roundQuantity(entered.mul(factor));const cost=roundUnitCost(decimal(line.unitCost??"0"));if((type==="RECEIPT"||type==="OPENING")&&cost.isNegative())throw fail("Receipt and opening unit cost cannot be negative.");await tx.stockDocumentLine.create({data:{companyId:company(req),documentId:document.id,lineNumber:i+1,itemId:item.id,locationId:loc.id,destinationLocationId:destId,enteredQuantity:entered,enteredUnitId:unitId,conversionFactor:factor,baseQuantity:base,unitCost:cost,lineValue:money(base.abs().mul(cost)),hsnSnapshot:null}});}
    await writeAuditEvent(tx,{...ctx(req),action:"inventory.document_created",targetType:"StockDocument",targetId:document.id,outcome:"SUCCESS",metadata:{type}});return tx.stockDocument.findUniqueOrThrow({where:{id:document.id},include:{lines:true}});
  },{isolationLevel:"Serializable"});respond(res,req,{document:created},201);
});
