route("post", "/stock-documents/:id/reverse", "inventory.cancel", async (req,res)=>{const id=String(req.params.id);const {reason}=z.object({reason:safeText.max(1000)}).parse(req.body);const key=z.string().min(8).max(128).parse(req.header("Idempotency-Key"));const requestHash=createHash("sha256").update(JSON.stringify({id,reason})).digest("hex");const previous=await prisma.stockIdempotencyRecord.findUnique({where:{companyId_operation_key:{companyId:company(req),operation:"reverse",key}}});if(previous){if(previous.requestHash!==requestHash)throw fail("Idempotency key was reused with a different reversal request.",409,"IDEMPOTENCY_CONFLICT");const document=await prisma.stockDocument.findFirst({where:{id:previous.resultDocumentId,companyId:company(req)},include:{lines:true}});respond(res,req,{document});return;}const original=await prisma.stockDocument.findFirst({where:{id,companyId:company(req),status:"POSTED"},include:{lines:true,financialYear:true}});if(!original)throw fail("Posted document not found.",404);if(await prisma.stockDocument.count({where:{companyId:company(req),reversalOfId:id}}))throw fail("Document has already been reversed.",409,"ALREADY_REVERSED");const companyRecord=await prisma.company.findUniqueOrThrow({where:{id:company(req)},select:{timezone:true}});const today=businessDate(new Date(),companyRecord.timezone);const todayDate=new Date(`${today}T00:00:00.000Z`);const fy=await prisma.financialYear.findFirst({where:{companyId:company(req),startDate:{lte:todayDate},endDate:{gte:todayDate},status:"OPEN"}});if(!fy)throw fail("An open current financial year is required for reversal.",409);const reversal=await retrySerializable(async()=>prisma.$transaction(async tx=>{await lockIdempotency(tx,company(req),"reverse:"+key);const replay=await tx.stockIdempotencyRecord.findUnique({where:{companyId_operation_key:{companyId:company(req),operation:"reverse",key}}});if(replay){if(replay.requestHash!==requestHash)throw fail("Idempotency key was reused with a different reversal request.",409,"IDEMPOTENCY_CONFLICT");return tx.stockDocument.findFirstOrThrow({where:{id:replay.resultDocumentId,companyId:company(req)},include:{lines:true}});}const reversalYearId=original.financialYear.status==="OPEN"?original.financialYearId:fy.id;for(const yearId of [...new Set([original.financialYearId,reversalYearId])].sort())await lockPeriod(tx,company(req),yearId);const originalYearNow=await tx.financialYear.findFirst({where:{id:original.financialYearId,companyId:company(req)}});const reversalYearNow=await tx.financialYear.findFirst({where:{id:reversalYearId,companyId:company(req)}});if(original.financialYear.status==="OPEN"&&originalYearNow?.status!=="OPEN")throw fail("The original period closed during reversal. Retry to use the current open period.",409,"PERIOD_CLOSED");if(!reversalYearNow||reversalYearNow.status!=="OPEN")throw fail("The reversal period is closed. Retry after selecting an open period.",409,"PERIOD_CLOSED");for(const itemId of [...new Set(original.lines.map(l=>l.itemId))].sort())await lockItem(tx,company(req),itemId);for(const line of original.lines){const later=await tx.stockLedgerEntry.findFirst({where:{companyId:company(req),itemId:line.itemId,documentId:{not:id},OR:[{effectiveDate:{gt:original.effectiveDate}},{effectiveDate:original.effectiveDate,createdAt:{gt:original.postedAt??original.createdAt}}]}});if(later)throw fail("Reverse dependent stock documents in reverse chronological order first.",409,"REVERSAL_DEPENDENCY");}const created=await tx.stockDocument.create({data:{companyId:company(req),financialYearId:original.financialYear.status==="OPEN"?original.financialYearId:fy.id,type:"REVERSAL",status:"POSTED",documentNumber:`REV-${randomUUID()}`,effectiveDate:original.financialYear.status==="OPEN"?original.effectiveDate:todayDate,reason,reversalOfId:id,createdByUserId:req.auth!.userId,postedByUserId:req.auth!.userId,postedAt:new Date(),lines:{create:original.lines.map(line=>({companyId:company(req),lineNumber:line.lineNumber,itemId:line.itemId,locationId:line.locationId,destinationLocationId:line.destinationLocationId,enteredQuantity:line.enteredQuantity,enteredUnitId:line.enteredUnitId,conversionFactor:line.conversionFactor,baseQuantity:line.baseQuantity.neg(),unitCost:line.unitCost,lineValue:line.lineValue}))}}});for(const entry of await tx.stockLedgerEntry.findMany({where:{companyId:company(req),documentId:id},include:{line:true}})){const qty=entry.signedBaseQuantity.neg(),value=entry.signedInventoryValue.neg();const balance=await tx.stockBalance.upsert({where:{companyId_itemId_locationId:{companyId:company(req),itemId:entry.itemId,locationId:entry.locationId}},create:{companyId:company(req),itemId:entry.itemId,locationId:entry.locationId,baseQuantity:qty,inventoryValue:value},update:{baseQuantity:{increment:qty},inventoryValue:{increment:value}}});if(balance.baseQuantity.lt(0))throw fail("Reversal would create negative stock.",409,"REVERSAL_UNSAFE");const reverseLine=await tx.stockDocumentLine.findUniqueOrThrow({where:{companyId_documentId_lineNumber:{companyId:company(req),documentId:created.id,lineNumber:entry.line.lineNumber}}});await tx.stockLedgerEntry.create({data:{companyId:company(req),itemId:entry.itemId,locationId:entry.locationId,documentId:created.id,lineId:reverseLine.id,effectiveDate:created.effectiveDate,signedBaseQuantity:qty,signedInventoryValue:value,unitCost:entry.unitCost,entryType:"REVERSAL",reversalOfId:entry.id}});}await tx.stockDocument.update({where:{id},data:{status:"REVERSED",reversedAt:new Date(),reversedByUserId:req.auth!.userId}});await tx.stockIdempotencyRecord.create({data:{companyId:company(req),operation:"reverse",key,requestHash,resultDocumentId:created.id}});await writeAuditEvent(tx,{...ctx(req),action:"inventory.document_reversed",targetType:"StockDocument",targetId:id,outcome:"SUCCESS",metadata:{reversalId:created.id,reason}});return tx.stockDocument.findUniqueOrThrow({where:{id:created.id},include:{lines:true}});},{isolationLevel:"Serializable"}));respond(res,req,{document:reversal},201);});

route("get", "/inventory/balances", "inventory.view", async (req,res)=>{const rows=await prisma.stockBalance.findMany({where:{companyId:company(req),...(req.query.itemId?{itemId:String(req.query.itemId)}:{}),...(req.query.locationId?{locationId:String(req.query.locationId)}:{})},include:{item:true,location:true},orderBy:{item:{name:"asc"}}});respond(res,req,{balances:rows});});
route("get", "/inventory/summary", "inventory.reports.view", async (req,res)=>{const [sum,items,balances]=await Promise.all([prisma.stockBalance.aggregate({where:{companyId:company(req)},_sum:{inventoryValue:true}}),prisma.item.findMany({where:{companyId:company(req),active:true},include:{balances:{where:{companyId:company(req)}}}}),prisma.stockBalance.count({where:{companyId:company(req)}})]);let lowStock=0,outOfStock=0;for(const item of items){const qty=item.balances.reduce((n,b)=>n.plus(b.baseQuantity),new Prisma.Decimal(0));if(qty.lte(0))outOfStock++;else if(qty.lte(item.reorderLevel))lowStock++;}respond(res,req,{totalInventoryValue:(sum._sum.inventoryValue??new Prisma.Decimal(0)).toString(),trackedItemLocations:balances,lowStock,outOfStock});});
route("get", "/inventory/low-stock", "inventory.reports.view", async (req,res)=>{const items=await prisma.item.findMany({where:{companyId:company(req),active:true},include:{balances:{where:{companyId:company(req)},include:{location:true}}},orderBy:{name:"asc"}});const alerts=items.map(item=>({item,baseQuantity:item.balances.reduce((n,b)=>n.plus(b.baseQuantity),new Prisma.Decimal(0))})).filter(row=>row.baseQuantity.lte(row.item.reorderLevel)).map(row=>({...row,baseQuantity:row.baseQuantity.toString(),outOfStock:row.baseQuantity.lte(0)}));respond(res,req,{alerts});});
route("get", "/inventory/ledger", "inventory.view", async (req,res)=>{const {q,skip,take}=listArgs(req);const where={companyId:company(req),...(req.query.itemId?{itemId:String(req.query.itemId)}:{}),...(req.query.locationId?{locationId:String(req.query.locationId)}:{}),...(req.query.from||req.query.to?{effectiveDate:{...(req.query.from?{gte:date.parse(req.query.from)}:{}),...(req.query.to?{lte:date.parse(req.query.to)}:{})}}:{})};const [entries,total]=await Promise.all([prisma.stockLedgerEntry.findMany({where,skip,take,include:{item:true,location:true,document:true},orderBy:[{effectiveDate:"desc"},{createdAt:"desc"}]}),prisma.stockLedgerEntry.count({where})]);respond(res,req,{entries,total,page:q.page,pageSize:take});});
route("get", "/inventory/reconciliation", "inventory.reconcile", async (req,res)=>{const discrepancies=await reconciliation(prisma,company(req));respond(res,req,{balanced:discrepancies.length===0,discrepancies});});
route("get", "/inventory/reports/:report", "inventory.reports.view", async (req,res)=>{const report=z.enum(["stock-summary","by-item","by-category","by-warehouse","by-bin","receipts","issues","transfers","adjustments","opening-stock","reversals"]).parse(req.params.report);if(["stock-summary","by-item","by-category","by-warehouse","by-bin"].includes(report)){const balances=await prisma.stockBalance.findMany({where:{companyId:company(req)},include:{item:{include:{category:true}},location:true}});if(report==="stock-summary"){respond(res,req,{rows:balances});return;}const groups=new Map<string,{label:string;quantity:Prisma.Decimal;value:Prisma.Decimal}>();for(const row of balances){if(report==="by-bin"&&row.location.type!=="BIN")continue;const key=report==="by-item"?row.itemId:report==="by-category"?row.item.categoryId??"uncategorized":report==="by-warehouse"?row.location.warehouseId:row.locationId;const label=report==="by-item"?`${row.item.code} · ${row.item.name}`:report==="by-category"?row.item.category?.name??"Uncategorized":report==="by-warehouse"?row.location.warehouseId:row.location.name;const current=groups.get(key)??{label,quantity:new Prisma.Decimal(0),value:new Prisma.Decimal(0)};current.quantity=current.quantity.plus(row.baseQuantity);current.value=current.value.plus(row.inventoryValue);groups.set(key,current);}respond(res,req,{rows:[...groups.entries()].map(([id,value])=>({id,...value,quantity:value.quantity.toString(),value:value.value.toString()}))});return;}const type=({receipts:"RECEIPT",issues:"ISSUE",transfers:"TRANSFER",adjustments:"ADJUSTMENT","opening-stock":"OPENING",reversals:"REVERSAL"} as const)[report as "receipts"|"issues"|"transfers"|"adjustments"|"opening-stock"|"reversals"];const documents=await prisma.stockDocument.findMany({where:{companyId:company(req),type},include:{lines:true,reversalOf:true,reversals:true},orderBy:{effectiveDate:"desc"},take:100});respond(res,req,{documents});});

function businessDate(now:Date,timezone:string){const parts=new Intl.DateTimeFormat("en-CA",{timeZone:timezone,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(now);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`;}
async function lockCompany(tx: Prisma.TransactionClient, companyId:string){await tx.$queryRaw`SELECT pg_advisory_xact_lock(hashtextextended(${companyId}, 18723))`;}
async function lockPeriod(tx: Prisma.TransactionClient, companyId:string, yearId:string){await tx.$queryRaw`SELECT pg_advisory_xact_lock(hashtextextended(${companyId+":fy:"+yearId}, 18723))`;}
async function lockIdempotency(tx: Prisma.TransactionClient, companyId:string,key:string){await tx.$queryRaw`SELECT pg_advisory_xact_lock(hashtextextended(${companyId+":idem:post:"+key}, 18723))`;}
async function lockLocationMode(tx:Prisma.TransactionClient,companyId:string,warehouseId:string){await tx.$queryRaw`SELECT pg_advisory_xact_lock(hashtextextended(${companyId+":warehouse-mode:"+warehouseId}, 18723))`;}
async function validateLocationMode(tx:Prisma.TransactionClient,companyId:string,locationId:string){const location=await tx.warehouseLocation.findFirst({where:{id:locationId,companyId,active:true}});if(!location)throw fail("Stock location is inactive or unavailable.",409);const direct=await tx.stockBalance.findFirst({where:{companyId,locationId:location.warehouseId,baseQuantity:{not:0}}});const bin=await tx.stockBalance.findFirst({where:{companyId,baseQuantity:{not:0},location:{companyId,warehouseId:location.warehouseId,type:"BIN"}}});if(location.type==="WAREHOUSE"&&bin)throw fail("This warehouse already contains bin-level stock; direct warehouse stock is blocked.",409,"MIXED_LOCATION_STOCK");if(location.type==="BIN"&&direct)throw fail("This warehouse contains direct stock; bin-level stock is blocked.",409,"MIXED_LOCATION_STOCK");}
async function lockItem(tx: Prisma.TransactionClient, companyId:string,itemId:string){await tx.$queryRaw`SELECT pg_advisory_xact_lock(hashtextextended(${companyId+":"+itemId}, 18723))`;}
async function retrySerializable<T>(fn:()=>Promise<T>):Promise<T>{for(let attempt=0;attempt<3;attempt++){try{return await fn();}catch(e){const code=(e as any)?.code;if(!["P2034","40P01","40001"].includes(code)||attempt===2)throw e;}}throw new Error("unreachable");}
async function reconciliation(db: any, companyId:string){const ledger=await db.stockLedgerEntry.groupBy({by:["itemId","locationId"],where:{companyId},_sum:{signedBaseQuantity:true,signedInventoryValue:true}});const balances=await db.stockBalance.findMany({where:{companyId}});const keys=new Set([...ledger.map((r:any)=>r.itemId+"|"+r.locationId),...balances.map((r:any)=>r.itemId+"|"+r.locationId)]);const byKey=new Map(balances.map((r:any)=>[r.itemId+"|"+r.locationId,r]));const sums=new Map(ledger.map((r:any)=>[r.itemId+"|"+r.locationId,r]));const result:any[]=[];for(const key of keys){const [itemId,locationId]=key.split("|");const l:any=sums.get(key),b:any=byKey.get(key);const qty=l?l._sum.signedBaseQuantity??new Prisma.Decimal(0):new Prisma.Decimal(0),value=l?l._sum.signedInventoryValue??new Prisma.Decimal(0):new Prisma.Decimal(0);const bq=b?.baseQuantity??new Prisma.Decimal(0),bv=b?.inventoryValue??new Prisma.Decimal(0);if(!qty.equals(bq)||!value.equals(bv))result.push({itemId,locationId,ledgerQuantity:qty.toString(),balanceQuantity:bq.toString(),ledgerValue:value.toString(),balanceValue:bv.toString(),missingProjection:!!l&&!b,unexpectedProjection:!!b&&!l});}return result;}
